        return 0

    def dist(i, j):
        if coords is None or i >= len(coords) or j >= len(coords) or coords[i] is None or coords[j] is None:
            return 0.0
        a = coords[i]
        b = coords[j]
        dx = a[0] - b[0]
        dy = a[1] - b[1]
        return (dx * dx + dy * dy) ** 0.5

    customers = list(range(1, n + 1))

    order = customers[:]
    if coords is not None and len(coords) > n:
        depot = coords[0]
        tmp = []
        for i in customers:
            if i >= len(coords) or coords[i] is None:
                tmp.append((2, 0, 0, i))
                continue
            x, y = coords[i]
            dx = x - depot[0]
            dy = y - depot[1]
            half = 0 if (dy > 0 or (dy == 0 and dx >= 0)) else 1
            cross_proxy = dy * 1.0 / (abs(dx) + abs(dy) + 1e-12)
            tmp.append((half, cross_proxy, dx * dx + dy * dy, i))
        tmp.sort()
        order = [t[3] for t in tmp]

    routes = []
    cur = []
    load = 0
    for c in order:
        d = demand_of(c)
        if cur and load + d > capacity:
            routes.append(cur)
            cur = []
            load = 0
        cur.append(c)
        load += d
    if cur:
        routes.append(cur)

    def route_load(r):
        s = 0
        for c in r:
            s += demand_of(c)
        return s

    def route_cost(r):
        if not r:
            return 0.0
        tot = dist(0, r[0])
        for i in range(len(r) - 1):
            tot += dist(r[i], r[i + 1])
        tot += dist(r[-1], 0)
        return tot

    def total_cost(rs):
        s = 0.0
        for r in rs:
            s += route_cost(r)
        return s

    changed = True
    while changed:
        changed = False
        for ri in range(len(routes)):
            r = routes[ri]
            if len(r) < 4:
                continue
            base = route_cost(r)
            best = None
            best_delta = 0.0
            m = len(r)
            for i in range(m - 2):
                for j in range(i + 2, m):
                    nr = r[:i + 1] + r[i + 1:j + 1][::-1] + r[j + 1:]
                    nc = route_cost(nr)
                    delta = nc - base
                    if delta < best_delta:
                        best_delta = delta
                        best = nr
            if best is not None:
                routes[ri] = best
                changed = True

    improved = True
    while improved:
        improved = False
        best_move = None
        best_gain = 0.0
        current_total = total_cost(routes)
        for i in range(len(routes)):
            ri = routes[i]
            for p, c in enumerate(ri):
                dc = demand_of(c)
                nri = ri[:p] + ri[p + 1:]
                cost_ri_new = route_cost(nri) if nri else 0.0
                cost_ri_old = route_cost(ri)
                for j in range(len(routes)):
                    if i == j:
                        continue
                    rj = routes[j]
                    if route_load(rj) + dc > capacity:
                        continue
                    best_pos = 0
                    best_rj = None
                    best_rj_cost = None
                    for pos in range(len(rj) + 1):
                        cand = rj[:pos] + [c] + rj[pos:]
                        cc = route_cost(cand)
                        if best_rj_cost is None or cc < best_rj_cost:
                            best_rj_cost = cc
                            best_rj = cand
                            best_pos = pos
                    if best_rj is None:
                        continue
                    gain = (cost_ri_old + route_cost(rj)) - (cost_ri_new + best_rj_cost)
                    if gain > best_gain:
                        best_gain = gain
                        best_move = (i, j, nri, best_rj)
        if best_move is not None:
            i, j, nri, new_rj = best_move
            routes[i] = nri
            routes[j] = new_rj
            routes = [r for r in routes if len(r) > 0]
            improved = True

    seen = {}
    for r in routes:
        for c in r:
            seen[c] = seen.get(c, 0) + 1

    missing = []
    for c in customers:
        if seen.get(c, 0) == 0:
            missing.append(c)

    for c in missing:
        dc = demand_of(c)
        best_idx = None
        best_cand = None
        best_delta = None
        for idx, r in enumerate(routes):
            if route_load(r) + dc > capacity:
                continue
            base = route_cost(r)
            for pos in range(len(r) + 1):
                cand = r[:pos] + [c] + r[pos:]
                cc = route_cost(cand)
                delta = cc - base
                if best_delta is None or delta < best_delta:
                    best_delta = delta
                    best_idx = idx
                    best_cand = cand
        if best_idx is not None:
            routes[best_idx] = best_cand
        else:
            routes.append([c])

    cleaned = []
    used = {}
    for r in routes:
        nr = []
        load = 0
        for c in r:
            if used.get(c, 0) == 0:
                d = demand_of(c)
                if load + d <= capacity:
                    nr.append(c)
                    load += d
                    used[c] = 1
        if nr:
            cleaned.append(nr)
    routes = cleaned

    present = {}
    for r in routes:
        for c in r:
            present[c] = 1
    for c in customers:
        if c not in present:
            routes.append([c])

    return routes
